 static double Luminance(Color c){double Part(byte v){double n=v/255.0;return n<=0.04045?n/12.92:Math.Pow((n+0.055)/1.055,2.4);}return .2126*Part(c.R)+.7152*Part(c.G)+.0722*Part(c.B);}
 static double Contrast(Brush a,Brush b){double x=Luminance(((SolidColorBrush)a).Color),y=Luminance(((SolidColorBrush)b).Color);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
 static void Screen(Window window,string path){TestActivation.Own(window);var hwnd=new WindowInteropHelper(window).Handle;Check(GetForegroundWindow()==hwnd&&GetWindowRect(hwnd,out _),"Own window capture only");GetWindowRect(hwnd,out var r);using var image=new System.Drawing.Bitmap(r.Right-r.Left,r.Bottom-r.Top);using var g=System.Drawing.Graphics.FromImage(image);g.CopyFromScreen(r.Left,r.Top,0,0,image.Size);image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}
 sealed class FailureHandler(string catalog):HttpMessageHandler
 {
  public readonly TaskCompletionSource<bool> Gate=new(TaskCreationOptions.RunContinuationsAsynchronously);public int ApiRequests,Downloads;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancel){if(request.RequestUri!.Host=="api.github.com"){Interlocked.Increment(ref ApiRequests);await Gate.Task.WaitAsync(cancel);return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(catalog)};}Interlocked.Increment(ref Downloads);throw new HttpRequestException("simulated refusal",new SocketException(10061));}
 }
